'use client';

import Sidebar from '@/components/layout/Sidebar';
import Header  from '@/components/layout/Header';
import { useAppStore } from '@/lib/store';

// ── Placeholder page views (will be replaced in later phases) ────────────
function PlaceholderPage({ title }: { title: string }) {
  return (
    <div className="flex flex-col items-center justify-center h-full min-h-[60vh] gap-4">
      <div
        className="w-16 h-16 rounded-2xl flex items-center justify-center"
        style={{ background: '#FEE4D4' }}
      >
        <svg width="28" height="28" viewBox="0 0 24 24" fill="none">
          <rect x="3" y="3" width="18" height="18" rx="4" fill="#E8540A" opacity="0.15"/>
          <path d="M12 8v4m0 4h.01" stroke="#E8540A" strokeWidth="2" strokeLinecap="round"/>
        </svg>
      </div>
      <h2 className="text-lg font-semibold" style={{ color: '#111111' }}>{title}</h2>
      <p className="text-sm" style={{ color: '#9CA3AF' }}>This section is coming soon.</p>
    </div>
  );
}

export default function AppShell() {
  const activePage = useAppStore((s) => s.activePage);

  const renderPage = () => {
    switch (activePage) {
      case 'home':
        return <PlaceholderPage title="Home" />;
      case 'my-groups':
        return <PlaceholderPage title="My Groups" />;
      case 'assignments':
        return <PlaceholderPage title="Assignments" />;
      case 'ai-toolkit':
        return <PlaceholderPage title="AI Toolkit" />;
      case 'my-library':
        return <PlaceholderPage title="My Library" />;
      case 'create-assignment':
        return <PlaceholderPage title="Create Assignment" />;
      case 'assignment-output':
        return <PlaceholderPage title="Assignment Output" />;
      default:
        return <PlaceholderPage title="Dashboard" />;
    }
  };

  return (
    <div className="flex min-h-screen" style={{ background: '#EBEBEB' }}>
      {/* Fixed Sidebar */}
      <Sidebar />

      {/* Main content area — offset from sidebar */}
      <div className="flex flex-col flex-1" style={{ marginLeft: '232px' }}>
        {/* Fixed Header */}
        <Header />

        {/* Scrollable Page Content */}
        <main
          className="flex-1 overflow-y-auto animate-fade-in"
          style={{ marginTop: '64px', padding: '24px 24px 40px' }}
        >
          {renderPage()}
        </main>
      </div>
    </div>
  );
}
