'use client';

import { useState, useRef, useEffect } from 'react';
import { useAppStore } from '@/lib/store';
import type { ActivePage } from '@/types';
import { Bell, ChevronDown, Search, Settings, LogOut, User, HelpCircle } from 'lucide-react';

// ── Breadcrumb config ──────────────────────────────────────────────────────
const PAGE_LABELS: Record<ActivePage, string> = {
  home:                'Home',
  'my-groups':         'My Groups',
  assignments:         'Assignments',
  'ai-toolkit':        'AI Toolkit',
  'my-library':        'My Library',
  'create-assignment': 'Create Assignment',
  'assignment-output': 'Assignment Output',
};

// ── Notification mock data ─────────────────────────────────────────────────
const NOTIFICATIONS = [
  { id: '1', text: 'Assignment "Quiz on Electricity" is due tomorrow.', time: '2m ago', unread: true },
  { id: '2', text: 'New student joined My Group – Science 8B.',          time: '1h ago', unread: true },
  { id: '3', text: 'Assignment generated successfully.',                  time: '3h ago', unread: false },
];

// ── Dropdown menu items ────────────────────────────────────────────────────
interface DropdownMenuItem {
  icon: React.ReactNode;
  label: string;
  id: string;
  danger?: boolean;
}

const USER_MENU: DropdownMenuItem[] = [
  { id: 'menu-profile',  icon: <User size={14} />,      label: 'My Profile'   },
  { id: 'menu-settings', icon: <Settings size={14} />,  label: 'Settings'     },
  { id: 'menu-help',     icon: <HelpCircle size={14} />,label: 'Help & Support'},
  { id: 'menu-logout',   icon: <LogOut size={14} />,    label: 'Sign Out', danger: true },
];

export default function Header() {
  const activePage        = useAppStore((s) => s.activePage);
  const searchQuery       = useAppStore((s) => s.searchQuery);
  const setSearchQuery    = useAppStore((s) => s.setSearchQuery);

  const [notifOpen, setNotifOpen]   = useState(false);
  const [userOpen,  setUserOpen]    = useState(false);

  const notifRef  = useRef<HTMLDivElement>(null);
  const userRef   = useRef<HTMLDivElement>(null);

  const unreadCount = NOTIFICATIONS.filter((n) => n.unread).length;

  // Close dropdowns on outside click
  useEffect(() => {
    function handler(e: MouseEvent) {
      if (notifRef.current && !notifRef.current.contains(e.target as Node)) setNotifOpen(false);
      if (userRef.current  && !userRef.current.contains(e.target as Node))  setUserOpen(false);
    }
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const pageLabel = PAGE_LABELS[activePage] ?? 'Dashboard';

  return (
    <header
      className="fixed top-0 left-[232px] right-0 z-20 flex items-center gap-4 px-6"
      style={{ height: '64px', background: 'rgba(235,235,235,0.85)', backdropFilter: 'blur(12px)' }}
    >
      {/* ── Breadcrumb / Title ──────────────────── */}
      <div className="flex items-center gap-2 flex-1">
        <span className="text-xs font-medium" style={{ color: '#9CA3AF' }}>
          VedaAI
        </span>
        <span style={{ color: '#D1D5DB', fontSize: '10px' }}>›</span>
        <span className="text-xs font-semibold" style={{ color: '#374151' }}>
          {pageLabel}
        </span>

        <div className="ml-4 flex-1 max-w-xs">
          {activePage === 'assignments' && (
            <div
              className="flex items-center gap-2 px-3 py-2 rounded-xl"
              style={{ background: 'rgba(255,255,255,0.8)', border: '1px solid #E5E7EB' }}
            >
              <Search size={14} style={{ color: '#9CA3AF', flexShrink: 0 }} />
              <input
                id="header-search"
                type="text"
                placeholder="Search assignments…"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="bg-transparent outline-none text-xs flex-1"
                style={{ color: '#111111' }}
              />
            </div>
          )}
        </div>
      </div>

      {/* ── Right Controls ──────────────────────── */}
      <div className="flex items-center gap-2">
        {/* Notification Bell */}
        <div className="relative" ref={notifRef}>
          <button
            id="btn-notifications"
            onClick={() => { setNotifOpen((v) => !v); setUserOpen(false); }}
            className="relative w-9 h-9 flex items-center justify-center rounded-xl transition-all duration-150"
            style={{ background: notifOpen ? '#F3F4F6' : 'rgba(255,255,255,0.7)', border: '1px solid #E5E7EB' }}
            onMouseEnter={(e) => (e.currentTarget.style.background = '#F3F4F6')}
            onMouseLeave={(e) => (e.currentTarget.style.background = notifOpen ? '#F3F4F6' : 'rgba(255,255,255,0.7)')}
          >
            <Bell size={16} style={{ color: '#374151' }} />
            {unreadCount > 0 && (
              <span
                className="absolute top-1 right-1 w-[7px] h-[7px] rounded-full"
                style={{ background: '#E8540A' }}
              />
            )}
          </button>

          {/* Notification Dropdown */}
          {notifOpen && (
            <div
              className="absolute right-0 mt-2 w-80 rounded-2xl shadow-veda-popup animate-fade-in overflow-hidden"
              style={{ background: 'white', border: '1px solid #F3F4F6', top: '100%' }}
            >
              <div className="flex items-center justify-between px-4 pt-4 pb-3">
                <h3 className="text-sm font-semibold" style={{ color: '#111111' }}>Notifications</h3>
                <span
                  className="text-xs font-medium px-2 py-0.5 rounded-full"
                  style={{ background: '#FEE4D4', color: '#E8540A' }}
                >
                  {unreadCount} new
                </span>
              </div>
              <div className="flex flex-col">
                {NOTIFICATIONS.map((n) => (
                  <div
                    key={n.id}
                    className="flex gap-3 px-4 py-3 cursor-pointer transition-colors"
                    style={{ background: n.unread ? '#FAFAFA' : 'white', borderTop: '1px solid #F3F4F6' }}
                    onMouseEnter={(e) => (e.currentTarget.style.background = '#F9FAFB')}
                    onMouseLeave={(e) => (e.currentTarget.style.background = n.unread ? '#FAFAFA' : 'white')}
                  >
                    {n.unread && (
                      <span className="mt-1.5 w-1.5 h-1.5 rounded-full flex-shrink-0" style={{ background: '#E8540A' }} />
                    )}
                    {!n.unread && <span className="mt-1.5 w-1.5 h-1.5 flex-shrink-0" />}
                    <div className="flex-1">
                      <p className="text-xs leading-relaxed" style={{ color: '#374151' }}>{n.text}</p>
                      <p className="text-[10px] mt-1" style={{ color: '#9CA3AF' }}>{n.time}</p>
                    </div>
                  </div>
                ))}
              </div>
              <div className="px-4 py-3 text-center" style={{ borderTop: '1px solid #F3F4F6' }}>
                <button className="text-xs font-medium" style={{ color: '#E8540A' }}>
                  Mark all as read
                </button>
              </div>
            </div>
          )}
        </div>

        {/* ── User Dropdown ─────────────────────── */}
        <div className="relative" ref={userRef}>
          <button
            id="btn-user-menu"
            onClick={() => { setUserOpen((v) => !v); setNotifOpen(false); }}
            className="flex items-center gap-2 pl-1 pr-3 py-1 rounded-xl transition-all duration-150"
            style={{
              background: userOpen ? '#F3F4F6' : 'rgba(255,255,255,0.7)',
              border: '1px solid #E5E7EB',
            }}
            onMouseEnter={(e) => (e.currentTarget.style.background = '#F3F4F6')}
            onMouseLeave={(e) => (e.currentTarget.style.background = userOpen ? '#F3F4F6' : 'rgba(255,255,255,0.7)')}
          >
            {/* Avatar */}
            <div
              className="w-7 h-7 rounded-lg flex items-center justify-center text-white text-xs font-semibold flex-shrink-0"
              style={{ background: 'linear-gradient(135deg, #E8540A 0%, #FF8C42 100%)' }}
            >
              S
            </div>
            <span className="text-xs font-semibold hidden sm:block" style={{ color: '#111111' }}>
              Samyak
            </span>
            <ChevronDown
              size={12}
              style={{
                color: '#9CA3AF',
                transform: userOpen ? 'rotate(180deg)' : 'rotate(0deg)',
                transition: 'transform 0.2s ease',
              }}
            />
          </button>

          {/* User Menu Dropdown */}
          {userOpen && (
            <div
              className="absolute right-0 mt-2 w-52 rounded-2xl shadow-veda-popup animate-fade-in overflow-hidden"
              style={{ background: 'white', border: '1px solid #F3F4F6', top: '100%' }}
            >
              {/* Profile header */}
              <div className="px-4 pt-4 pb-3" style={{ borderBottom: '1px solid #F3F4F6' }}>
                <p className="text-xs font-semibold" style={{ color: '#111111' }}>Samyak Srijan</p>
                <p className="text-[10px] mt-0.5" style={{ color: '#9CA3AF' }}>samyak@vedaai.com</p>
              </div>
              {USER_MENU.map((item) => (
                <button
                  key={item.id}
                  id={item.id}
                  className="w-full flex items-center gap-3 px-4 py-2.5 text-xs transition-colors text-left"
                  style={{ color: item.danger ? '#DC2626' : '#374151' }}
                  onMouseEnter={(e) => (e.currentTarget.style.background = item.danger ? '#FEF2F2' : '#F9FAFB')}
                  onMouseLeave={(e) => (e.currentTarget.style.background = 'transparent')}
                >
                  <span style={{ opacity: 0.7 }}>{item.icon}</span>
                  {item.label}
                </button>
              ))}
            </div>
          )}
        </div>
      </div>
    </header>
  );
}
